package com.loadouts;

import com.google.gson.Gson;
import java.util.Arrays;
import net.runelite.client.config.ConfigManager;
import org.junit.Assert;
import org.junit.Before;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.mockito.Mock;
import org.mockito.junit.MockitoJUnitRunner;

import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

@RunWith(MockitoJUnitRunner.class)
public class LoadoutStoreTest
{
	private static final String GROUP = LoadoutStore.CONFIG_GROUP;

	@Mock
	private ConfigManager configManager;

	private LoadoutStore store;

	@Before
	public void setUp()
	{
		store = new LoadoutStore(configManager, new Gson());
	}

	@Test
	public void keysAreStandardized()
	{
		when(configManager.getConfiguration(GROUP, "snapshot.zulrah")).thenReturn("{}");

		Assert.assertTrue(store.exists("<col=ff0000>Zulrah</col>"));
		Assert.assertFalse(store.exists("vorkath"));
	}

	@Test
	public void corruptJsonReturnsNull()
	{
		when(configManager.getConfiguration(GROUP, "snapshot.zulrah")).thenReturn("{not-json");

		Assert.assertNull(store.get("zulrah"));
	}

	@Test
	public void malformedArraysAreReplaced()
	{
		when(configManager.getConfiguration(GROUP, "snapshot.zulrah"))
			.thenReturn("{\"inventory\":[{\"itemId\":4151,\"quantity\":1}],\"equipment\":null}");

		LoadoutSnapshot snapshot = store.get("zulrah");
		Assert.assertEquals(LoadoutSnapshot.INVENTORY_SIZE, snapshot.getInventory().length);
		Assert.assertEquals(LoadoutSnapshot.EQUIPMENT_SIZE, snapshot.getEquipment().length);
		Assert.assertTrue(snapshot.isEmpty());
	}

	@Test
	public void setShowingFalseUnsetsKey()
	{
		store.setShowing("zulrah", false);

		verify(configManager).unsetConfiguration(GROUP, "showing.zulrah");
	}

	@Test
	public void clearAllShowingUnsetsAllKeys()
	{
		when(configManager.getConfigurationKeys(GROUP + ".showing."))
			.thenReturn(Arrays.asList(GROUP + ".showing.zulrah", GROUP + ".showing.vorkath"));

		store.clearAllShowing();

		verify(configManager).unsetConfiguration(GROUP, "showing.zulrah");
		verify(configManager).unsetConfiguration(GROUP, "showing.vorkath");
	}
}

package com.loadouts;

import org.junit.Assert;
import org.junit.Test;

public class LoadoutRequirementsTest
{
	@Test
	public void acceptsNormalTagNames()
	{
		Assert.assertTrue(LoadoutRequirements.isValidTag("zulrah"));
		Assert.assertTrue(LoadoutRequirements.isValidTag("<col=ff0000>zulrah</col>"));
	}

	@Test
	public void rejectsBlankTagsAndPlaceholders()
	{
		Assert.assertFalse(LoadoutRequirements.isValidTag(null));
		Assert.assertFalse(LoadoutRequirements.isValidTag(""));
		Assert.assertFalse(LoadoutRequirements.isValidTag("   "));
		Assert.assertFalse(LoadoutRequirements.isValidTag(LoadoutMessages.chooseTagPrompt()));
	}

	@Test
	public void normalizeTagStripsColorTags()
	{
		Assert.assertEquals("zulrah", LoadoutRequirements.normalizeTag("<col=ff0000>zulrah</col>"));
		Assert.assertEquals("", LoadoutRequirements.normalizeTag(null));
	}
}

