public class LoadoutSnapshotTest
{
	@Test
	public void emptySnapshotReportsEmpty()
	{
		LoadoutSnapshot snapshot = new LoadoutSnapshot();
		Assert.assertFalse(snapshot.hasInventory());
		Assert.assertFalse(snapshot.hasEquipment());
		Assert.assertTrue(snapshot.isEmpty());
	}

	@Test
	public void inventoryOnlySnapshot()
	{
		LoadoutSnapshot snapshot = new LoadoutSnapshot();
		snapshot.getInventory()[0] = LoadoutSlot.of(1, 1);
		Assert.assertTrue(snapshot.hasInventory());
		Assert.assertFalse(snapshot.hasEquipment());
		Assert.assertFalse(snapshot.isEmpty());
	}

