	public void equipmentOnlySnapshot()
	{
		LoadoutSnapshot snapshot = new LoadoutSnapshot();
		snapshot.getEquipment()[0] = LoadoutSlot.of(1, 1);
		Assert.assertFalse(snapshot.hasInventory());
		Assert.assertTrue(snapshot.hasEquipment());
		Assert.assertFalse(snapshot.isEmpty());
	}
}

package com.loadouts;

import net.runelite.api.EquipmentInventorySlot;
import net.runelite.client.plugins.banktags.tabs.Layout;
import org.junit.Assert;
import org.junit.Test;

public class LoadoutLayoutFactoryTest
{
	@Test
	public void inventoryFillsLeftFourColumns()
	{
		LoadoutSnapshot snapshot = new LoadoutSnapshot();
		snapshot.getInventory()[0] = LoadoutSlot.of(1, 1);
		snapshot.getInventory()[4] = LoadoutSlot.of(2, 1);
		snapshot.getInventory()[27] = LoadoutSlot.of(3, 1);

		Layout layout = LoadoutLayoutFactory.build("t", snapshot);
		Assert.assertEquals(1, layout.getItemAtPos(0));
		Assert.assertEquals(2, layout.getItemAtPos(8));
		Assert.assertEquals(3, layout.getItemAtPos(51));
		Assert.assertEquals(-1, layout.getItemAtPos(1));
		Assert.assertEquals(-1, layout.getItemAtPos(4));
	}

	@Test
	public void equipmentSilhouetteUsesColumnsFiveToSeven()
	{
		LoadoutSnapshot snapshot = new LoadoutSnapshot();
		snapshot.getEquipment()[EquipmentInventorySlot.HEAD.getSlotIdx()] = LoadoutSlot.of(999, 1);
		snapshot.getEquipment()[EquipmentInventorySlot.RING.getSlotIdx()] = LoadoutSlot.of(555, 1);

		Layout layout = LoadoutLayoutFactory.build("t", snapshot);
		Assert.assertEquals(999, layout.getItemAtPos(6));
		Assert.assertEquals(555, layout.getItemAtPos(4 * 8 + 7));
		Assert.assertEquals(-1, layout.getItemAtPos(5));
		Assert.assertEquals(-1, layout.getItemAtPos(7));
	}

	@Test
	public void slotAtDistinguishesBlankCellsFromCellsOutsideTheLoadout()
	{
		LoadoutSnapshot snapshot = new LoadoutSnapshot();
		snapshot.getInventory()[0] = LoadoutSlot.of(1, 1);
		snapshot.getEquipment()[EquipmentInventorySlot.HEAD.getSlotIdx()] = LoadoutSlot.of(999, 1);

		Assert.assertEquals(1, LoadoutLayoutFactory.slotAt(snapshot, 0).getItemId());
		Assert.assertTrue(LoadoutLayoutFactory.slotAt(snapshot, 1).isEmpty());
		Assert.assertTrue(LoadoutLayoutFactory.slotAt(snapshot, 5).isEmpty());
		Assert.assertNull(LoadoutLayoutFactory.slotAt(snapshot, 4));
		Assert.assertNull(LoadoutLayoutFactory.slotAt(snapshot, LoadoutLayoutFactory.LAYOUT_SIZE));
	}

	@Test
	public void sectionsWithoutItemsAreOutsideTheLoadout()
	{
		LoadoutSnapshot inventoryOnly = new LoadoutSnapshot();
		inventoryOnly.getInventory()[0] = LoadoutSlot.of(1, 1);
		Assert.assertNull(LoadoutLayoutFactory.slotAt(inventoryOnly, 6));

		LoadoutSnapshot equipmentOnly = new LoadoutSnapshot();
		equipmentOnly.getEquipment()[EquipmentInventorySlot.HEAD.getSlotIdx()] = LoadoutSlot.of(999, 1);
		Assert.assertNull(LoadoutLayoutFactory.slotAt(equipmentOnly, 0));
	}
}

package com.loadouts;

import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.widgets.ItemQuantityMode;
import net.runelite.api.widgets.Widget;
import net.runelite.client.game.ItemManager;
import net.runelite.client.plugins.banktags.BankTagsPlugin;
import net.runelite.client.plugins.banktags.BankTagsService;
import net.runelite.client.plugins.banktags.tabs.Layout;

@Slf4j
@Singleton
public class LoadoutBankView
{
	static final String LAYOUT_TAG_PREFIX = "__loadouts_";

	/** Read-only: the view is rebuilt from the snapshot, so tag or layout edits made here would be lost. */
	private static final int SHOW_OPTIONS = BankTagsService.OPTION_ITEMS_NOT_IN_LAYOUT_AT_BOTTOM;

	private final Client client;
	private final ItemManager itemManager;
	private final BankTagsPlugin bankTagsPlugin;
	private final LoadoutRequirements requirements;

	@Inject
	public LoadoutBankView(
		Client client,
		ItemManager itemManager,
		BankTagsPlugin bankTagsPlugin,
		LoadoutRequirements requirements)
	{
		this.client = client;
		this.itemManager = itemManager;
		this.bankTagsPlugin = bankTagsPlugin;
		this.requirements = requirements;
	}

	public static String layoutTagFor(String tag)
	{
		return LAYOUT_TAG_PREFIX + tag;
	}

	public boolean isLoadoutLayoutActive(String tag)
	{
		Layout layout = bankTagsPlugin.getActiveLayout();
		return layout != null && layoutTagFor(tag).equals(layout.getTag());
	}

	public LoadoutSlot[] captureInventory()
	{
		return capture(InventoryID.INV, LoadoutSnapshot.INVENTORY_SIZE);
	}

	public LoadoutSlot[] captureEquipment()
	{
		return capture(InventoryID.WORN, LoadoutSnapshot.EQUIPMENT_SIZE);
	}

	private LoadoutSlot[] capture(int inventoryId, int size)
	{
		LoadoutSlot[] slots = LoadoutSnapshot.emptySlots(size);
		ItemContainer container = client.getItemContainer(inventoryId);
		if (container == null)
		{
			return slots;
		}
		for (int i = 0; i < size; i++)
		{
			Item item = container.getItem(i);
			if (item != null && item.getId() > 0 && item.getQuantity() > 0)
			{
				slots[i] = LoadoutSlot.of(itemManager.canonicalize(item.getId()), item.getQuantity());
			}
		}
		return slots;
	}

	public boolean show(String tag, LoadoutSnapshot snapshot)
	{
		if (!requirements.isBankOpen() || !requirements.isBankTagsActive() || snapshot.isEmpty())
		{
			return false;
		}
		try
		{
			bankTagsPlugin.openTag(tag, LoadoutLayoutFactory.build(layoutTagFor(tag), snapshot), SHOW_OPTIONS);
			applyQuantities(snapshot);
			return true;
		}
		catch (Exception e)
		{
			log.warn("Failed to show loadout for tag {}", tag, e);
			return false;
		}
	}

	public boolean hide(String tag)
	{
		if (!requirements.isBankOpen() || !requirements.isBankTagsActive())
		{
			return false;
		}
		try
		{
			bankTagsPlugin.openBankTag(tag, BankTagsService.OPTION_ALLOW_MODIFICATIONS);
			return true;
		}
		catch (Exception e)
		{
			log.warn("Failed to hide loadout for tag {}", tag, e);
			return false;
		}
	}

	/** Hides every bank cell outside the loadout and overlays the saved trip quantities on the rest. */
	public void applyQuantities(LoadoutSnapshot snapshot)
	{
		Widget container = client.getWidget(InterfaceID.Bankmain.ITEMS);
		Widget[] children = container == null ? null : container.getChildren();
		if (children == null)
		{
			return;
		}
		for (int i = 0; i < children.length; i++)
		{
			Widget child = children[i];
			if (child == null)
			{
				continue;
			}
			LoadoutSlot slot = LoadoutLayoutFactory.slotAt(snapshot, i);
			// Tab separators are shorter than an item and would cut through the grid; tagged items
			// that are not in the loadout are packed after the layout and would break the shape.
			if (child.getOriginalHeight() < BankTagsPlugin.BANK_ITEM_HEIGHT || slot == null || slot.isEmpty())
			{
				child.setHidden(true);
				continue;
			}
			child.setHidden(false);
			child.setItemQuantity(slot.getQuantity());
			child.setItemQuantityMode(ItemQuantityMode.ALWAYS);
		}
	}
}

package com.loadouts;

import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.plugins.PluginManager;
import net.runelite.client.plugins.banktags.BankTagsPlugin;
import net.runelite.client.util.Text;

@Singleton
public class LoadoutRequirements
{
	private final Client client;
	private final PluginManager pluginManager;
	private final BankTagsPlugin bankTagsPlugin;

	@Inject
	LoadoutRequirements(Client client, PluginManager pluginManager, BankTagsPlugin bankTagsPlugin)
	{
		this.client = client;
		this.pluginManager = pluginManager;
		this.bankTagsPlugin = bankTagsPlugin;
	}

	public boolean isBankOpen()
	{
		if (client.getItemContainer(InventoryID.BANK) == null)
		{
			return false;
		}
		Widget items = client.getWidget(InterfaceID.Bankmain.ITEMS);
		return items != null && !items.isHidden();
	}

	public boolean isBankTagsActive()
	{
		return pluginManager.isPluginActive(bankTagsPlugin);
	}

	public static boolean isValidTag(String tag)
	{
		return !normalizeTag(tag).isEmpty();
	}

	/** Strips colour tags and placeholders such as {@code <choose tag>}, which normalize to empty. */
	public static String normalizeTag(String tag)
	{
		return tag == null ? "" : Text.removeTags(tag).trim();
	}
}

package com.loadouts;

import java.util.Arrays;
import lombok.Data;

@Data
public class LoadoutSnapshot
{
	public static final int INVENTORY_SIZE = 28;
	public static final int EQUIPMENT_SIZE = 14;

	private LoadoutSlot[] inventory = emptySlots(INVENTORY_SIZE);
	private LoadoutSlot[] equipment = emptySlots(EQUIPMENT_SIZE);

	public boolean hasInventory()
	{
		return hasItems(inventory);
	}

	public boolean hasEquipment()
	{
		return hasItems(equipment);
	}

	public boolean isEmpty()
	{
		return !hasInventory() && !hasEquipment();
	}

	public static boolean hasItems(LoadoutSlot[] slots)
	{
		return slots != null && Arrays.stream(slots).anyMatch(s -> s != null && !s.isEmpty());
	}

	public static LoadoutSlot[] emptySlots(int size)
	{
		LoadoutSlot[] slots = new LoadoutSlot[size];
		Arrays.setAll(slots, i -> LoadoutSlot.empty());
		return slots;
	}
}

package com.loadouts;

import com.google.gson.Gson;
import com.google.gson.JsonSyntaxException;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.util.Text;

@Slf4j
@Singleton
public class LoadoutStore
{
	static final String CONFIG_GROUP = "load-out-helper";
	private static final String SNAPSHOT_PREFIX = "snapshot.";
	private static final String SHOWING_PREFIX = "showing.";

	private final ConfigManager configManager;
	private final Gson gson;

	@Inject
	public LoadoutStore(ConfigManager configManager, Gson gson)
	{
		this.configManager = configManager;
		this.gson = gson;
	}

	/** Cheap presence check for menu building; use {@link #get} when the contents are needed. */
	public boolean exists(String tag)
	{
		return configManager.getConfiguration(CONFIG_GROUP, snapshotKey(tag)) != null;
	}

	public LoadoutSnapshot get(String tag)
	{
		String json = configManager.getConfiguration(CONFIG_GROUP, snapshotKey(tag));
		if (json == null)
		{
			return null;
		}
		try
		{
			LoadoutSnapshot snapshot = gson.fromJson(json, LoadoutSnapshot.class);
			if (snapshot == null)
			{
				return null;
			}
			if (snapshot.getInventory() == null || snapshot.getInventory().length != LoadoutSnapshot.INVENTORY_SIZE)
			{
				snapshot.setInventory(LoadoutSnapshot.emptySlots(LoadoutSnapshot.INVENTORY_SIZE));
			}
			if (snapshot.getEquipment() == null || snapshot.getEquipment().length != LoadoutSnapshot.EQUIPMENT_SIZE)
			{
				snapshot.setEquipment(LoadoutSnapshot.emptySlots(LoadoutSnapshot.EQUIPMENT_SIZE));
			}
			return snapshot;
		}
		catch (JsonSyntaxException e)
		{
			log.warn("Failed to parse loadout for tag {}", tag);
			return null;
		}
	}

	public void put(String tag, LoadoutSnapshot snapshot)
	{
		configManager.setConfiguration(CONFIG_GROUP, snapshotKey(tag), gson.toJson(snapshot));
	}

	public boolean isShowing(String tag)
	{
		return Boolean.parseBoolean(configManager.getConfiguration(CONFIG_GROUP, showingKey(tag)));
	}

	public void setShowing(String tag, boolean showing)
	{
		if (showing)
		{
			configManager.setConfiguration(CONFIG_GROUP, showingKey(tag), "true");
		}
		else
		{
			configManager.unsetConfiguration(CONFIG_GROUP, showingKey(tag));
		}
	}

	public void clearAllShowing()
	{
		String groupPrefix = CONFIG_GROUP + ".";
		for (String fullKey : configManager.getConfigurationKeys(groupPrefix + SHOWING_PREFIX))
		{
			configManager.unsetConfiguration(CONFIG_GROUP, fullKey.substring(groupPrefix.length()));
		}
	}

	private static String snapshotKey(String tag)
	{
		return SNAPSHOT_PREFIX + Text.standardize(tag);
	}

	private static String showingKey(String tag)
	{
		return SHOWING_PREFIX + Text.standardize(tag);
	}
}

package com.loadouts;

import java.awt.Color;
import java.util.function.Consumer;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.MenuAction;
import net.runelite.api.ScriptID;
import net.runelite.api.events.MenuEntryAdded;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.api.events.ScriptPostFired;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.chat.ChatMessageManager;
import net.runelite.client.chat.QueuedMessage;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.game.chatbox.ChatboxPanelManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDependency;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.plugins.banktags.BankTagsPlugin;
import net.runelite.client.ui.JagexColors;
import net.runelite.client.util.ColorUtil;

@Slf4j
@PluginDescriptor(
	name = "Load-Out Helper",
	description = "Save inventory and equipment loadouts on Bank Tags tabs and show a 4x7 bag layout",
	tags = {"bank", "tags", "inventory", "equipment", "loadout", "gear", "helper"}
)
@PluginDependency(BankTagsPlugin.class)
public class LoadoutsPlugin extends Plugin
{
	private static final String SAVE_INVENTORY = "Save inventory loadout";
	private static final String SAVE_EQUIPMENT = "Save equipment loadout";
	private static final String SHOW_LOADOUT = "Show loadout";
	private static final String HIDE_LOADOUT = "Hide loadout";
	private static final String VIEW_TAB = "View tag tab";
	private static final Color HILIGHT_COLOR = JagexColors.MENU_TARGET;

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private ChatboxPanelManager chatboxPanelManager;

	@Inject
	private ChatMessageManager chatMessageManager;

	@Inject
	private LoadoutStore store;

	@Inject
	private LoadoutBankView bankView;

	@Inject
	private LoadoutRequirements requirements;

	@Inject
	private BankTagsPlugin bankTagsPlugin;

	@Override
	protected void startUp()
	{
		log.info("Load-Out Helper started");
		if (!requirements.isBankTagsActive())
		{
			sendChat(LoadoutMessages.bankTagsRequired());
		}
	}

	@Override
	protected void shutDown()
	{
		store.clearAllShowing();
		log.info("Load-Out Helper stopped");
	}

	@Subscribe
	public void onMenuEntryAdded(MenuEntryAdded event)
	{
		if (!requirements.isBankTagsActive())
		{
			return;
		}

		if (event.getActionParam1() == InterfaceID.Bankmain.DEPOSITINV
			&& event.getOption().equals("Deposit inventory"))
		{
			addSaveEntry(event, SAVE_INVENTORY);
		}
		else if (event.getActionParam1() == InterfaceID.Bankmain.DEPOSITWORN
			&& event.getOption().equals("Deposit worn items"))
		{
			addSaveEntry(event, SAVE_EQUIPMENT);
		}
		else if (event.getOption().equals(VIEW_TAB))
		{
			String tag = LoadoutRequirements.normalizeTag(event.getTarget());
			if (LoadoutRequirements.isValidTag(tag) && store.exists(tag))
			{
				createMenu(event, store.isShowing(tag) ? HIDE_LOADOUT : SHOW_LOADOUT, ColorUtil.wrapWithColorTag(tag, HILIGHT_COLOR));
			}
		}
	}

	private void addSaveEntry(MenuEntryAdded event, String option)
	{
		String active = bankTagsPlugin.getActiveTag();
		String target = active != null && !active.isEmpty()
			? ColorUtil.wrapWithColorTag(active, HILIGHT_COLOR)
			: LoadoutMessages.chooseTagPrompt();
		createMenu(event, option, target);
	}

	private void createMenu(MenuEntryAdded event, String option, String target)
	{
		client.getMenu().createMenuEntry(-1)
			.setParam0(event.getActionParam0())
			.setParam1(event.getActionParam1())
			.setTarget(target)
			.setOption(option)
			.setType(MenuAction.RUNELITE)
			.setIdentifier(event.getIdentifier());
	}

	@Subscribe
	public void onMenuOptionClicked(MenuOptionClicked event)
	{
		if (event.getMenuAction() != MenuAction.RUNELITE)
		{
			return;
		}

		String tag = LoadoutRequirements.normalizeTag(event.getMenuTarget());
		switch (event.getMenuOption())
		{
			case SAVE_INVENTORY:
				event.consume();
				save(tag, true);
				break;
			case SAVE_EQUIPMENT:
				event.consume();
				save(tag, false);
				break;
			case SHOW_LOADOUT:
				event.consume();
				show(tag);
				break;
			case HIDE_LOADOUT:
				event.consume();
				hide(tag);
				break;
			default:
				break;
		}
	}

	/**
	 * Bank Tags restores the tab's own saved layout whenever the bank is rebuilt (reopen, View tag tab),
	 * replacing our ephemeral {@code __loadouts_} layout. Rebuild it when that happens; otherwise only
	 * overlay quantities. {@link BankTagsPlugin#openTag} must not run inside BANKMAIN_FINISHBUILDING
	 * because scripts are not reentrant, so the rebuild is deferred to the next client tick.
	 */
	@Subscribe
	public void onScriptPostFired(ScriptPostFired event)
	{
		if (event.getScriptId() != ScriptID.BANKMAIN_FINISHBUILDING)
		{
			return;
		}
		String tag = bankTagsPlugin.getActiveTag();
		if (tag == null || !store.isShowing(tag) || !requirements.isBankOpen())
		{
			return;
		}
		if (!requirements.isBankTagsActive())
		{
			store.setShowing(tag, false);
			return;
		}

		LoadoutSnapshot snapshot = store.get(tag);
		if (snapshot == null || snapshot.isEmpty())
		{
			store.setShowing(tag, false);
			sendChat(LoadoutMessages.corruptLoadout(tag));
			return;
		}

		if (bankView.isLoadoutLayoutActive(tag))
		{
			bankView.applyQuantities(snapshot);
			return;
		}
		clientThread.invokeLater(() ->
		{
			if (store.isShowing(tag) && !bankView.isLoadoutLayoutActive(tag) && !bankView.show(tag, snapshot))
			{
				log.warn("Deferred show failed for tag {}", tag);
			}
		});
	}

	private void save(String tag, boolean inventory)
	{
		if (LoadoutRequirements.isValidTag(tag))
		{
			saveToTag(tag, inventory);
			return;
		}
		String kind = inventory ? "inventory" : "equipment";
		chatboxPanelManager.openTextInput("Save " + kind + " loadout to tag:")
			.onDone((Consumer<String>) name -> clientThread.invoke(() ->
			{
				String typed = LoadoutRequirements.normalizeTag(name);
				if (LoadoutRequirements.isValidTag(typed))
				{
					saveToTag(typed, inventory);
				}
			}))
			.build();
	}

	private void saveToTag(String tag, boolean inventory)
	{
		if (!checkBankReady())
		{
			return;
		}

		LoadoutSnapshot snapshot = store.get(tag);
		if (snapshot == null)
		{
			snapshot = new LoadoutSnapshot();
		}

		LoadoutSlot[] captured = inventory ? bankView.captureInventory() : bankView.captureEquipment();
		if (!LoadoutSnapshot.hasItems(captured))
		{
			sendChat(inventory ? LoadoutMessages.emptyInventory() : LoadoutMessages.emptyEquipment());
			return;
		}
		if (inventory)
		{
			snapshot.setInventory(captured);
			sendChat(LoadoutMessages.savedInventory(tag));
		}
		else
		{
			snapshot.setEquipment(captured);
			sendChat(LoadoutMessages.savedEquipment(tag));
		}

		store.put(tag, snapshot);
		if (store.isShowing(tag) && tag.equals(bankTagsPlugin.getActiveTag()) && !bankView.show(tag, snapshot))
		{
			sendChat(LoadoutMessages.showFailed());
		}
	}

	private void show(String tag)
	{
		if (!checkBankReady())
		{
			return;
		}
		LoadoutSnapshot snapshot = store.get(tag);
		if (snapshot == null || snapshot.isEmpty())
		{
			sendChat(LoadoutMessages.noLoadout(tag));
			return;
		}
		store.setShowing(tag, true);
		if (!bankView.show(tag, snapshot))
		{
			store.setShowing(tag, false);
			sendChat(LoadoutMessages.showFailed());
			return;
		}
		sendChat(LoadoutMessages.showing(tag));
	}

	private void hide(String tag)
	{
		if (!checkBankReady())
		{
			return;
		}
		store.setShowing(tag, false);
		if (!bankView.hide(tag))
		{
			sendChat(LoadoutMessages.showFailed());
			return;
		}
		sendChat(LoadoutMessages.hid(tag));
	}

	/** Reports the first unmet precondition to the user and returns whether all are met. */
	private boolean checkBankReady()
	{
		if (!requirements.isBankOpen())
		{
			sendChat(LoadoutMessages.bankClosed());
			return false;
		}
		if (!requirements.isBankTagsActive())
		{
			sendChat(LoadoutMessages.bankTagsRequired());
			return false;
		}
		return true;
	}

	private void sendChat(String message)
	{
		chatMessageManager.queue(QueuedMessage.builder()
			.type(ChatMessageType.CONSOLE)
			.runeLiteFormattedMessage(message)
			.build());
	}
}

