package com.loadouts;

import lombok.Data;

@Data
public class LoadoutSlot
{
	private int itemId = -1;
	private int quantity;

	public boolean isEmpty()
	{
		return itemId <= 0 || quantity <= 0;
	}

	public static LoadoutSlot empty()
	{
		return new LoadoutSlot();
	}

	public static LoadoutSlot of(int itemId, int quantity)
	{
		LoadoutSlot slot = new LoadoutSlot();
		slot.itemId = itemId;
		slot.quantity = quantity;
		return slot;
	}
}

package com.loadouts;

import net.runelite.api.EquipmentInventorySlot;
import net.runelite.client.plugins.banktags.tabs.Layout;

/**
 * Maps a loadout onto the 8-wide bank grid: the 4x7 inventory fills columns 0-3 and the
 * worn-equipment silhouette (3 wide, 5 tall) fills columns 5-7.
 */
final class LoadoutLayoutFactory
{
	static final int BANK_COLUMNS = 8;
	static final int INVENTORY_COLUMNS = 4;
	static final int INVENTORY_ROWS = 7;
	static final int EQUIPMENT_COLUMN = 5;
	static final int EQUIPMENT_COLUMNS = 3;
	static final int LAYOUT_SIZE = INVENTORY_ROWS * BANK_COLUMNS;

	/** Worn slot for each equipment cell, row-major; -1 is a blank cell in the silhouette. */
	private static final int[] EQUIPMENT_FORMAT = {
		-1, EquipmentInventorySlot.HEAD.getSlotIdx(), -1,
		EquipmentInventorySlot.CAPE.getSlotIdx(), EquipmentInventorySlot.AMULET.getSlotIdx(), EquipmentInventorySlot.AMMO.getSlotIdx(),
		EquipmentInventorySlot.WEAPON.getSlotIdx(), EquipmentInventorySlot.BODY.getSlotIdx(), EquipmentInventorySlot.SHIELD.getSlotIdx(),
		-1, EquipmentInventorySlot.LEGS.getSlotIdx(), -1,
		EquipmentInventorySlot.GLOVES.getSlotIdx(), EquipmentInventorySlot.BOOTS.getSlotIdx(), EquipmentInventorySlot.RING.getSlotIdx()
	};

	private LoadoutLayoutFactory()
	{
	}

	static Layout build(String layoutTag, LoadoutSnapshot snapshot)
	{
		Layout layout = new Layout(layoutTag);
		layout.resize(LAYOUT_SIZE);
		for (int pos = 0; pos < LAYOUT_SIZE; pos++)
		{
			LoadoutSlot slot = slotAt(snapshot, pos);
			if (slot != null && !slot.isEmpty())
			{
				layout.setItemAtPos(slot.getItemId(), pos);
			}
		}
		return layout;
	}

	/**
	 * @return the loadout slot displayed at a bank grid position, or null when the position
	 * is outside the loadout shape
	 */
	static LoadoutSlot slotAt(LoadoutSnapshot snapshot, int bankIndex)
	{
		int row = bankIndex / BANK_COLUMNS;
		int col = bankIndex % BANK_COLUMNS;
		if (row >= INVENTORY_ROWS)
		{
			return null;
		}
		if (col < INVENTORY_COLUMNS)
		{
			return snapshot.hasInventory() ? snapshot.getInventory()[row * INVENTORY_COLUMNS + col] : null;
		}
		int formatIndex = row * EQUIPMENT_COLUMNS + (col - EQUIPMENT_COLUMN);
		if (col < EQUIPMENT_COLUMN || formatIndex >= EQUIPMENT_FORMAT.length || !snapshot.hasEquipment())
		{
			return null;
		}
		int worn = EQUIPMENT_FORMAT[formatIndex];
		return worn < 0 ? LoadoutSlot.empty() : snapshot.getEquipment()[worn];
	}
}
